def cachedmethod(cls_or_self, cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    from functools import wraps

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            hashkey = key(*args, **kwargs)
            try:
                return cache[hashkey]
            except KeyError:
                pass
            result = func(cls_or_self, *args, **kwargs)
            cache[hashkey] = result
            return result
        return wrapper
    if isinstance(cls_or_self, type):
        for attr in dir(cls_or_self):
            try:
                func = getattr(cls_or_self, attr)
            except AttributeError:
                continue
            if not callable(func):
                continue
            setattr(cls_or_self, attr, decorator(func))
    else:
        for attr in dir(cls_or_self):
            try:
                func = getattr(cls_or_self, attr)
            except AttributeError:
                continue
            if not callable(func):
                continue
            setattr(cls_or_self, attr, decorator(func))

    return cls_or_self

