def minimalBases(classes):
    assert isinstance(classes, list)
    included = {}
    while classes:
        current = classes.pop()
        included[current.__name__] = True
        # All base classes of current are also included
        for base in current.__bases__:
            if base.__name__ not in included:
                classes.append(base)
    return included.keys()

