def _update_context(self, context):
    """
    Update the context with the properties of this graph.

    The 'error' subcontext of the context is updated with indices of errors.
    The 'error_E_low', 'error_E_high', 'error_E_none', 'error_t_low',
    'error_t_high', and 'error_t_none' subcontexts are created if they do not
    already exist. The 'error_E_low', 'error_E_high', 'error_t_low', and
    'error_t_high' subcontexts are updated with the indices of errors that
    have a low, high, low, and high value, respectively. The 'error_E_none'
    and 'error_t_none' subcontexts are updated with the indices of errors that
    do not have a low, high, low, or high value, respectively.

    Called on "destruction" of the graph (for example, in the
    .ToCSV). By destruction we mean conversion to another structure
    (like text) in the flow. The graph object is not really destroyed
    in this process.
    """
    if 'error' not in context:
        context['error'] = {}

    if 'error_E_low' not in context['error']:
        context['error']['error_E_low'] = []

    if 'error_E_high' not in context['error']:
        context['error']['error_E_high'] = []

    if 'error_E_none' not in context['error']:
        context['error']['error_E_none'] = []

    if 'error_t_low' not in context['error']:
        context['error']['error_t_low'] = []

    if 'error_t_high' not in context['error']:
        context['error']['error_t_high'] = []

    if 'error_t_none' not in context['error']:
        context['error']['error_t_none'] = []

    for error in self.errors:
        if error.low is not None:
            context['error']['error_E_low'].append(error.index)
            if error.high is not None:
                context['error']['error_E_high'].append(error.index)
            else:
                context['error']['error_E_none'].append(error.index)
        else:
            if error.high is not None:
                context['error']['error_t_high'].append(error.index)
            else:
                context['error']['error_t_none'].append(error.index)

