def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dictionary")

    # Check that the manifest files is a list of strings
    if not isinstance(manifest_files, list) or not all(isinstance(file, str) for file in manifest_files):
        raise ValueError("Manifest files is not a list of strings")

    # Check that all files listed in the fixity block are in the manifest
    for file in fixity:
        if file not in manifest_files:
            raise ValueError(f"File {file} listed in fixity block but not in manifest")

    # Check that all files listed in the manifest are referenced in the fixity block
    for file in manifest_files:
        if file not in fixity:
            raise ValueError(f"File {file} listed in manifest but not in fixity block")

    # All checks passed
    return True

