def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """

    def _recursive_format(obj, indent=0, debug=False):
        pretty_repr = []
        for key, value in obj.items():
            pretty_repr.append(f"{key}: {value}")

        if debug:
            pretty_repr.append(f"      type: {type(obj)}")

        return "\n".join([
            " " * indent + line
            for line in pretty_repr
        ])

    if isinstance(self, dict):
        return _recursive_format(self, indent, debug)

    elif isinstance(self, list):
        return "-" + "\n".join([
            _recursive_format(value, indent + 2, debug)
            for value in self
        ])

    elif isinstance(self, str):
        return f'"{self}"'

    else:
        return f"{self}"

