def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """

        new_args = []
        for arg in args:
            if isinstance(arg, Operator):
                if arg.oper == "|":
                    new_args.append(arg.args[0])
                elif arg.oper == "&" and isinstance(arg.args[1], Operator):
                    if arg.args[1].oper == "|":
                        new_args.append(Operator("&", [arg.args[0], arg.args[1].args[1]]))
                    elif arg.args[1].oper == "&":
                        new_args.append(Operator("&", [arg.args[0], arg.args[1].args[1]]))
                    else:
                        new_args.append(arg)
                else:
                    new_args.append(arg)
            else:
                new_args.append(arg)
        return new_args

