def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.get_inventory()
    version_inventories = [self.get_inventory(version_dir) for version_dir in version_dirs]
    version_content_digests = {}

    # Check each version inventory
    for version, inventory in enumerate(version_inventories):
        # Check that the inventory exists for this version
        if not inventory:
            raise InventoryNotFoundError("Inventory not found for version {}".format(version))

        # Check that the inventory is up to date
        if inventory.timestamp > root_inventory.timestamp:
            raise InventoryOutdatedError("Inventory for version {} is outdated".format(version))

        # Check that the inventory is consistent with the root inventory
        if inventory.differs(root_inventory):
            raise InventoryMismatchError("Inventory for version {} differs from the root inventory".format(version))

        # Record content digests for any content that is different from the root inventory
        for item in inventory.items:
            if item.type == "content" and item.digest != root_inventory.items[item.name].digest:
                version_content_digests[item.name] = item.digest

    return version_content_digests

