def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("Interface not provided: " + str(iface))
    for methodname, method in list(iface.methods.items()):
        try:
            meth = getattr(candidate, methodname)
        except AttributeError:
            raise zope.interface.Invalid("No method: " + methodname)
        if not hasattr(meth, '__func__'):
            raise zope.interface.Invalid("Method does not have a __func__ attribute: " + methodname)
        if not hasattr(meth, '__code__') or not hasattr(meth.__func__, '__code__'):
            raise zope.interface.Invalid("Method does not have a valid __code__ attribute: " + methodname)

        for argname, arg in list(method.arguments.items()):
                try:
                    argtype = eval(arg.type)
                    needsconversion = False
                except NameError:
                    pass:
                else:
                    if not isinstance(meth, functools.partial):
                        needsconversion = True
                    else:
                        methkwargs = inspect.getfullargspec(meth.__func__)
                        if len(methkwargs.kwonlyargs) > 0:
                            needsconversion = True
                            continue
                        for a,kwarg in enumerate(methkwargs.args[-len(argname):]):
                            if argname.startswith('?'):
                                if kwarg != 'kwargs': raise zope.interface.Invalid("Unexpected keyword argument: " + argname)
                                continue
                            else:
                                if kwarg != argname: needsconversion = True
                                else:
                                    break
                        else:
                            if a < len(argname):
                                needsconversion = True
                    if needsconversion:
                        raise zope.interface.Invalid("Argument conversion failed for: " + argname)
                        continue

                if not issubclass(meth.__code__.co_argcount, argtype):
                    raise zope.interface.Invalid("Argument conversion failed for: " + argname)

    for attribname, attrib in list(iface.attributes.items()):
        try:
            attrib = getattr(candidate, attribname)
        except AttributeError:
            raise zope.interface.Invalid("Missing attribute: " + attribname)
        if not hasattr(attrib, '__func__'):
            raise zope.interface.Invalid("Attribute is not a callable: " + attribname)
        if not hasattr(attrib, '__code__') or not hasattr(attrib.__func__, '__code__'):
            raise zope.interface.Invalid("Attribute does not have a valid __code__ attribute: " + attribname)

    return True

